checks.command:
node --input-type=module - <<'NODE'
import fs from 'node:fs';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {createRequire} from 'node:module';
import {artifactDigest,taskContractDigest} from './scripts/remediation/board.mjs';
const require=createRequire(import.meta.url),{parsePatch,applyPatch}=require('diff'),read=p=>JSON.parse(fs.readFileSync(p,'utf8')),sha=v=>crypto.createHash('sha256').update(v).digest('hex');
const d='docs/remediation/evidence/W13.01/',a=read(d+'artifact.json'),w=read(d+'worker.json'),b=read(d+'baseline.json'),s=read(d+'source-basis.json'),c=read('docs/remediation/design/W13.01/task-contract-v1.json');
assert.equal(artifactDigest(a),a.digest);assert.equal(taskContractDigest(c),a.contract_digest);for(const f of a.files)assert.equal(sha(fs.readFileSync(f.path)),f.sha256,f.path);
for(const f of s.files)assert.ok(a.files.some(p=>p.path===f.path&&p.sha256===f.sha256),f.path);
const patches=parsePatch(w.artifact.admission_patch);assert.equal(patches.length,9);assert.equal(sha(w.artifact.admission_patch),w.artifact.admission_patch_sha256);
for(const f of w.artifact.files){const old=b.files.find(p=>p.path===f.path),patch=patches.find(p=>p.oldFileName==='a/'+f.path);assert.equal(sha(old.content),old.sha256);assert.equal(old.sha256,f.before_sha256);assert.equal(sha(fs.readFileSync(f.path)),f.sha256);assert.equal(applyPatch(old.content,patch),fs.readFileSync(f.path,'utf8'),f.path);}
const owned=new Set(w.artifact.files.map(f=>f.path));for(const f of b.lint_source_pins)if(!owned.has(f.path))assert.equal(sha(fs.readFileSync(f.path)),f.sha256,f.path);assert.equal(b.lint_source_pins.length,281);
assert.equal(w.checks.find(v=>v.id==='W13.01-K1').command,c.checks.find(v=>v.id==='W13.01-K1').command);assert.equal(w.checks.find(v=>v.id==='W13.01-K2').command,c.checks.find(v=>v.id==='W13.01-K2').command);assert.ok(w.checks.every(v=>v.exit_code===0));
const text=w.checks.find(v=>v.id==='W13.01-K1').stdout,warningRows=text.split('\n').filter(l=>/^\s+\d+:\d+\s+warning\s/.test(l));assert.equal(warningRows.length,503);assert.equal(text.split('\n').filter(l=>/^\s+\d+:\d+\s+error\s/.test(l)).length,0);assert.match(text,/503 problems \(0 errors, 503 warnings\)/);
console.log(JSON.stringify({at:new Date().toISOString(),artifact_digest:a.digest,contract_digest:a.contract_digest,pins:a.files.length,source_pins:s.files.length,lint_source_pins:b.lint_source_pins.length,verified_admission_patches:patches.length,unowned_lint_drift:[],worker_error_rows:0,worker_warning_rows:503,worker_checks:w.checks.map(v=>({id:v.id,exit_code:v.exit_code})),artifact_file_sha256:sha(fs.readFileSync(d+'artifact.json')),worker_file_sha256:sha(fs.readFileSync(d+'worker.json'))},null,2));
NODE

node --input-type=module - <<'NODE'
import fs from 'node:fs';import crypto from 'node:crypto';import assert from 'node:assert/strict';
const a=JSON.parse(fs.readFileSync('docs/remediation/evidence/W13.01/artifact.json','utf8'));for(const f of a.files)assert.equal(crypto.createHash('sha256').update(fs.readFileSync(f.path)).digest('hex'),f.sha256,f.path);console.log(JSON.stringify({at:new Date().toISOString(),verified_pins:a.files.length,drift:[]}));
NODE
